// Hazy Homunculus
// status: ready
// This creature can't be blocked as long as defending player controls an untapped land.
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (q.state().battlefield().iter().copied().filter(|&id| q.controller(id) == Some(asker.source).and_then(|o: ObjectId| q.state().attackers.iter().find(|a| a.id == o).map(|a| a.defending)).unwrap_or(PlayerId(u8::MAX)) && (!(q.state().obj(id).tapped) && q.chars(id).is(CardType::Land))).count() >= 1) && (source == affected) }
#[allow(unused_variables)] fn ability_0_0_0_keyword(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); if q.state().battlefield().iter().copied().filter(|&id| q.controller(id) == Some(asker.source).and_then(|o: ObjectId| q.state().attackers.iter().find(|a| a.id == o).map(|a| a.defending)).unwrap_or(PlayerId(u8::MAX)) && (!(q.state().obj(id).tapped) && q.chars(id).is(CardType::Land))).count() >= 1 { chars.keywords = chars.keywords.with(Keyword::CantBeBlocked); } }

